package org.dextur.reputation.paper;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.bukkit.*;
import org.bukkit.attribute.*;
import org.bukkit.entity.Player;
import org.bukkit.command.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.dextur.reputation.api.*;
import org.dextur.reputation.application.*;
import org.dextur.reputation.domain.PlayerLanguage;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.*;
import org.junit.jupiter.params.provider.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class PolicyAdaptersTest {
    @org.junit.jupiter.api.io.TempDir java.nio.file.Path directory;
    @Test void policyPanelHonorsBaseUsePermissionBeforeAnyRead()throws Exception{var plugin=mock(DexturReputationPlugin.class);var policies=mock(PolicyApplication.class);when(policies.configuration()).thenReturn(PolicyConfiguration.load(directory));var commands=mock(PolicyCommands.class);var player=mock(Player.class);when(player.hasPermission("dexturreputation.policies")).thenReturn(true);var effects=new PolicyEffects(plugin,policies,commands,Messages.bundled(PlayerLanguage.ru_RU),new PolicyEffects.Layout(true,48,27,Material.BOOK));effects.open(player);verify(commands).send(player,"no-permission",Map.of());verify(policies,never()).evaluate(any(),any());}
    ReputationPolicyResult result(double health){return new ReputationPolicyResult(UUID.randomUUID(),"health.maximum",ReputationPolicyResult.Decision.LIMITED,0,"NEUTRAL","",null,java.math.BigDecimal.ONE,java.math.BigDecimal.valueOf(health),"policy-reason-configured",new ReputationPolicyResult.Revision(1,0,0,"config"),Instant.EPOCH,true);}
    static final class Health {
        final Player player=mock(Player.class);final AttributeInstance attribute=mock(AttributeInstance.class);final List<AttributeModifier> modifiers=new ArrayList<>();final AtomicReference<Double> health=new AtomicReference<>(20.0);
        Health(){when(attribute.getBaseValue()).thenReturn(20.0);when(attribute.getModifiers()).thenAnswer(i->List.copyOf(modifiers));when(attribute.getValue()).thenAnswer(i->{double add=0,scalar=0,multiply=1;for(var m:modifiers)switch(m.getOperation()){case ADD_NUMBER->add+=m.getAmount();case ADD_SCALAR->scalar+=m.getAmount();case MULTIPLY_SCALAR_1->multiply*=1+m.getAmount();}return (20+add)*(1+scalar)*multiply;});doAnswer(i->{modifiers.add(i.getArgument(0));return null;}).when(attribute).addTransientModifier(any());doAnswer(i->{modifiers.remove(i.getArgument(0));return null;}).when(attribute).removeModifier(any(AttributeModifier.class));when(player.getHealth()).thenAnswer(i->health.get());doAnswer(i->{double value=i.getArgument(0);assertTrue(value>0&&value<=attribute.getValue());health.set(value);return null;}).when(player).setHealth(anyDouble());}
    }
    @ParameterizedTest @ValueSource(doubles={16,18,21,24})void healthDoesNotStackAndCleanupIsReversible(double target){var h=new Health();PolicyEffects.health(h.player,h.attribute,result(target),true);PolicyEffects.health(h.player,h.attribute,result(target),true);assertEquals(target,h.attribute.getValue());assertEquals(1,h.modifiers.size());verify(h.attribute,times(1)).addTransientModifier(any());assertTrue(h.health.get()>0&&h.health.get()<=target);PolicyEffects.remove(h.player,h.attribute);assertEquals(20,h.attribute.getValue());assertTrue(h.modifiers.isEmpty());verify(h.attribute,never()).setBaseValue(anyDouble());}
    @Test void foreignModifiersArePreservedAndCurrentHealthClampsSafely(){var h=new Health();var foreign=new AttributeModifier(new NamespacedKey("foreign","boost"),4,AttributeModifier.Operation.ADD_NUMBER);h.modifiers.add(foreign);h.health.set(24.0);PolicyEffects.health(h.player,h.attribute,result(16),true);assertEquals(20,h.attribute.getValue());assertEquals(20,h.health.get());assertTrue(h.modifiers.contains(foreign));PolicyEffects.remove(h.player,h.attribute);assertEquals(List.of(foreign),h.modifiers);assertEquals(24,h.attribute.getValue());verify(h.attribute,never()).removeModifier(foreign);}
    @Test void disabledPolicyRemovesOnlyOwnedModifier(){var h=new Health();PolicyEffects.health(h.player,h.attribute,result(24),true);h.health.set(24.0);PolicyEffects.health(h.player,h.attribute,result(24),false);assertEquals(20,h.attribute.getValue());assertEquals(20,h.health.get());assertTrue(h.modifiers.isEmpty());}
    @Test void unsafeForeignCombinationDoesNotApplyHarmfulOwnedModifier(){var h=new Health();h.modifiers.add(new AttributeModifier(new NamespacedKey("foreign","reduction"),-17,AttributeModifier.Operation.ADD_NUMBER));h.health.set(3.0);PolicyEffects.health(h.player,h.attribute,result(16),true);assertEquals(3,h.attribute.getValue());assertEquals(1,h.modifiers.size());verify(h.player,never()).setHealth(0);verify(h.attribute,never()).addTransientModifier(any());}
    @Test void scalarForeignEffectsRemainIntact(){var h=new Health();h.modifiers.add(new AttributeModifier(new NamespacedKey("foreign","scalar"),0.5,AttributeModifier.Operation.ADD_SCALAR));h.modifiers.add(new AttributeModifier(new NamespacedKey("foreign","multiply"),0.1,AttributeModifier.Operation.MULTIPLY_SCALAR_1));PolicyEffects.health(h.player,h.attribute,result(16),true);assertEquals(26.4,h.attribute.getValue(),0.000001);PolicyEffects.remove(h.player,h.attribute);assertEquals(33,h.attribute.getValue(),0.000001);assertEquals(2,h.modifiers.size());}
    @Test void separatePermissionsDenyEveryMutation()throws Exception{var plugin=mock(DexturReputationPlugin.class);when(plugin.ready()).thenReturn(true);var app=mock(ReputationApplication.class);var policies=mock(PolicyApplication.class);var sender=mock(CommandSender.class);var settings=mock(Settings.class);when(settings.defaultLanguage()).thenReturn(PlayerLanguage.ru_RU);var commands=new PolicyCommands(plugin,app,policies,settings,Messages.bundled(PlayerLanguage.ru_RU));var command=mock(Command.class);for(String[] args:List.of(new String[]{"set","Player","100","reason"},new String[]{"add","Player","25","reason"},new String[]{"remove","Player","25","reason"},new String[]{"voting","lock","Player","reason"},new String[]{"policy","Player","chat.send","allow","reason"},new String[]{"reload"}))commands.onCommand(sender,command,"repadmin",args);verifyNoInteractions(policies);assertTrue(commands.onTabComplete(sender,command,"repadmin",new String[]{""}).isEmpty());}
    @Test void policyPlaceholdersAreCacheOnlyAndSwitchable()throws Exception{var plugin=mock(DexturReputationPlugin.class);when(plugin.ready()).thenReturn(true);var app=mock(ReputationApplication.class);var policies=mock(PolicyApplication.class);var player=mock(OfflinePlayer.class);when(player.getUniqueId()).thenReturn(UUID.randomUUID());var bridge=new PlaceholderBridge(plugin,app,Messages.bundled(PlayerLanguage.ru_RU));bridge.policies(policies,true);var effects=mock(PolicyEffects.class);when(effects.modifier(any(),any())).thenReturn(Optional.of("0"));bridge.healthEffects(effects);when(policies.cached(any(),any())).thenReturn(Optional.empty());assertEquals("",bridge.onRequest(player,"policy_vote"));when(policies.cached(any(),any())).thenReturn(Optional.of(result(24)));when(policies.configuration()).thenReturn(PolicyConfiguration.load(directory));assertEquals("LIMITED",bridge.onRequest(player,"policy_chat_send"));assertEquals("0",bridge.onRequest(player,"health_modifier"));bridge.policies(policies,false);assertEquals("",bridge.onRequest(player,"policy_vote"));verify(policies,never()).evaluate(any(),any(),any());verifyNoInteractions(app);}
    @Test void policyGuiCancelsTransfersAndDrags()throws Exception{var plugin=mock(DexturReputationPlugin.class);var policies=mock(PolicyApplication.class);var commands=mock(PolicyCommands.class);var effects=new PolicyEffects(plugin,policies,commands,Messages.bundled(PlayerLanguage.ru_RU),new PolicyEffects.Layout(true,48,27,Material.BOOK));var panel=new PolicyEffects.Panel(UUID.randomUUID());panel.inventory=mock(Inventory.class);when(panel.inventory.getHolder()).thenReturn(panel);var view=mock(InventoryView.class);when(view.getTopInventory()).thenReturn(panel.inventory);var click=mock(InventoryClickEvent.class);when(click.getView()).thenReturn(view);effects.click(click);verify(click).setCancelled(true);var drag=mock(InventoryDragEvent.class);when(drag.getView()).thenReturn(view);effects.drag(drag);verify(drag).setCancelled(true);verifyNoInteractions(policies);}
}
